def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves."""
    result = set()
    _diff(before, after, "", result)
    return sorted(result)


def _diff(before, after, prefix, result):
    for key in before:
        if key not in after:
            path = f"{prefix}.{key}" if prefix else key
            result.add(path)
    for key in after:
        if key not in before:
            path = f"{prefix}.{key}" if prefix else key
            result.add(path)
    for key in before:
        if key in after:
            path = f"{prefix}.{key}" if prefix else key
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _diff(b_val, a_val, path, result)
            elif b_val != a_val:
                result.add(path)
