def coalesce(intervals):
    """Merge overlapping or touching half-open integer intervals (start, end).

    - Discards empty intervals (start == end).
    - Raises ValueError if start > end.
    - Returns a sorted list of tuples without mutating the input.
    """
    valid = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"invalid interval: start ({start}) > end ({end})")
        if start == end:
            continue
        valid.append((start, end))

    if not valid:
        return []

    valid.sort(key=lambda t: t[0])

    merged = [valid[0]]
    for start, end in valid[1:]:
        prev_start, prev_end = merged[-1]
        if start <= prev_end:
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))

    return merged
```

