def frames(lines):
    result = []
    data_fields = []

    for line in lines:
        if line == "":
            # Blank line: dispatch the event
            if data_fields:
                result.append("\n".join(data_fields))
            data_fields = []
        elif line.startswith(":"):
            # Comment: ignore
            pass
        else:
            colon_idx = line.find(":")
            if colon_idx == -1:
                field = line
                value = ""
            else:
                field = line[:colon_idx]
                value = line[colon_idx + 1:]
                if value.startswith(" "):
                    value = value[1:]

            if field == "data":
                data_fields.append(value)

    # Remaining data_fields without a blank-line terminator are discarded

    return result
