from copy import deepcopy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    Overlay values replace base values. If both values for a key are dicts,
    they are merged recursively. A None in overlay does not delete the key;
    it simply sets the value to None. The result is deep-independent of
    both inputs (no shared references, no mutation of inputs).
    """
    result = {}
    for key in base:
        if key in overlay:
            base_val = base[key]
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = deepcopy(overlay_val)
        else:
            result[key] = deepcopy(base[key])
    for key in overlay:
        if key not in base:
            result[key] = deepcopy(overlay[key])
    return result
