def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Rejects non-absolute paths with ValueError.
    - Collapses repeated slashes.
    - Ignores '.' components.
    - Resolves '..' components without going above root.
    - Returns '/' for root, never a trailing slash otherwise.
    - No filesystem access.
    """
    if not path.startswith('/'):
        raise ValueError(f"Path must be absolute: {path!r}")

    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack is empty, '..' is ignored (can't go above root)
        else:
            stack.append(part)

    return '/' + '/'.join(stack)
```

