def pack(items, max_bytes):
    """Greedily pack consecutive items into batches whose total UTF-8 byte length <= max_bytes."""
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    if not items:
        return []

    # Validate that every individual item fits within max_bytes
    for item in items:
        if len(item.encode('utf-8')) > max_bytes:
            raise ValueError(
                f"Item does not fit within {max_bytes} bytes: {item!r}"
            )

    result = []
    current_batch = []
    current_size = 0

    for item in items:
        item_bytes = len(item.encode('utf-8'))
        if current_batch and current_size + item_bytes > max_bytes:
            result.append(current_batch)
            current_batch = []
            current_size = 0
        current_batch.append(item)
        current_size += item_bytes

    if current_batch:
        result.append(current_batch)

    return result
```

