import heapq


def order(deps):
    # Collect all nodes (keys and values)
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Build prerequisite set for every node (do not mutate deps)
    prereqs_map = {}
    for node in nodes:
        prereqs_map[node] = set(deps[node]) if node in deps else set()

    # Reverse graph: node -> list of nodes that depend on it
    dependents = {node: [] for node in nodes}
    in_degree = {}
    for node in nodes:
        in_degree[node] = len(prereqs_map[node])
        for p in prereqs_map[node]:
            dependents[p].append(node)

    # Min-heap for alphabetically smallest ready node
    heap = []
    for node in nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
```

